/* Modules (HMODULE): the program, the translated modules of the game and
   the system DLLs that the runtime implements (see rt_module.c). */
#ifndef RT_MODULE_H
#define RT_MODULE_H

#include "rt.h"

#include <stdbool.h>

/* One import that the runtime implements (generated by tools/gen_thunks.py).
   name is NULL for an import by ordinal. */
typedef struct rt_import_entry {
    const char *dll; /* lower case, without ".dll" */
    const char *name;
    uint32_t ordinal;
    char *addr;
} rt_import_entry;

extern const rt_import_entry rt_import_table[];
extern const unsigned rt_import_table_count;

/* The pointer initialization of the translated modules (llasm -ptrofs).
   Each module puts its initialize_pointers function at the start of this
   chain when the image loads; each function calls the previous one. The
   function writes each pointer of the module data as a guest address
   (host address minus ptrofs). It must run one time, after rt_mem_init
   and before guest code runs. */
extern void (*ptr_initialize_pointers)(uint64_t ptrofs);

/* Guest directory of the game and of the system DLLs. */
#define RT_GUEST_GAME_DIR "C:\\PillarsOfEternity"
#define RT_GUEST_WINDOWS_DIR "C:\\Windows"
#define RT_GUEST_SYSTEM_DIR "C:\\Windows\\system32"

/* Make the module list: the program module with the guest path
   exe_guest_path, and the system DLLs. Call it after rt_mem_init. */
void rt_modules_init(const char *exe_guest_path);

/* Map a translated DLL of the game: the player's file host_path (it must
   have the SHA-256 sha256, in lower case hexadecimal) at its original image
   base, with the import address table bound to the runtime thunks and the
   code map registered (rt_code_register). guest_path is the Windows path of
   the file. Returns the module handle (the image base). Stops the process
   for every error. The DLL is not attached: call rt_module_attach_static. */
uint32_t rt_module_load_pe(const char *guest_path, const char *host_path, const char *sha256, const uint8_t *code_map);

/* As rt_module_load_pe, but map the DLL at the guest address load_base of
   its translation (a copy rebased with tools/rebase_pe.py). If load_base
   is not the preferred base, the base relocations are applied, as the
   Windows loader does. Use it when the preferred base of the DLL is not
   free (for example, the base of mono.dll). */
uint32_t rt_module_load_pe_at(const char *guest_path, const char *host_path, const char *sha256, const uint8_t *code_map,
                              uint32_t load_base);

/* Map the translated program file (an exe of the game) as the program
   module: the player's file host_path (SHA-256 sha256) at the guest address
   load_base of the translation. If load_base is not the preferred base,
   the base relocations are applied, as the Windows loader does. The
   import address table is bound and the code map is registered.
   guest_path must be the path of rt_modules_init. Returns load_base. Stops
   the process for every error. */
uint32_t rt_module_load_program(const char *guest_path, const char *host_path, const char *sha256, const uint8_t *code_map,
                                uint32_t load_base);

/* The original address of the entry point of a mapped translated module.
   Stops the process if the module has no entry point. */
uint32_t rt_module_entry(uint32_t base);

/* Load a mapped DLL as an import of the program: one reference, then
   DllMain with DLL_PROCESS_ATTACH. Stops the process if DllMain fails. */
void rt_module_attach_static(_cpu *cpu, uint32_t base);

/* The original address of the export name of a translated module. Stops
   the process if there is no such export. */
uint32_t rt_module_export(uint32_t base, const char *name);

/* GetProcAddress(base, name) gives addr in place of the export of the
   translated module at base. Call before guest code runs. At most
   RT_MAX_EXPORT_OVERRIDES overrides; one more stops the process. */
#define RT_MAX_EXPORT_OVERRIDES 4
void rt_module_override_export(uint32_t base, const char *name, uint32_t addr);

/* The SizeOfImage of a mapped PE module (the program or a loaded
   translated DLL), or 0 if h is not such a module. h == 0: the program. */
uint32_t rt_module_image_size(uint32_t h);

/* The program (exe) module handle. */
uint32_t rt_exe_module(void);
/* The guest path (UTF-8) of the program file (GetModuleFileName of the
   program module). */
const char *rt_exe_guest_path(void);

/* End the process (ExitProcess): DLL detach notifications, then exit. Does
   not return. */
_Noreturn void rt_process_exit(uint32_t code);

#endif
